<?php
$notice='';$booking=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$ref=strtoupper(trim((string)($_POST['reference']??'')));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);if($ref&&$email){$q=db()->prepare('SELECT b.*,p.full_name,t.depart_at,t.arrive_at,r.train_code,a.name origin,c.name destination,GROUP_CONCAT(bs.seat_code SEPARATOR ", ") seats FROM bookings b JOIN passengers p ON p.booking_id=b.id JOIN trips t ON t.id=b.trip_id JOIN routes r ON r.id=t.route_id JOIN stations a ON a.id=r.from_station_id JOIN stations c ON c.id=r.to_station_id LEFT JOIN booking_seats bs ON bs.booking_id=b.id WHERE b.reference=? AND b.email=? GROUP BY b.id');$q->execute([$ref,$email]);$booking=$q->fetch()?:null;if(!$booking)$notice='No booking matched that reference and email.';}}
?>
<section class="page-banner"><div class="container"><p class="eyebrow">CHANGE OF PLANS?</p><h1>Manage a <em>booking.</em></h1><p>Look up a booking to review its status and request a change.</p></div></section><section class="container content-section"><form method="post" class="lookup-form two-fields"><?= csrf_field() ?><label>Booking reference<input name="reference" required maxlength="8" pattern="[A-Za-z0-9]{6,8}" placeholder="e.g. A1B2C3D4"></label><label>Booking email<input type="email" name="email" required maxlength="190" placeholder="you@example.com"></label><button class="button primary">Find booking →</button></form><?php if($notice): ?><p class="inline-error"><?= h($notice) ?></p><?php endif; ?><?php if($booking): ?><article class="manage-card"><div class="manage-card-head"><div><p class="eyebrow">BOOKING <?= h($booking['reference']) ?></p><h2><?= h($booking['origin']) ?> <span>→</span> <?= h($booking['destination']) ?></h2></div><span class="pill <?= $booking['status']==='confirmed'?'green':'gray' ?>"><?= h($booking['status']) ?></span></div><div class="ticket-details"><span>Passenger<strong><?= h($booking['full_name']) ?></strong></span><span>Departure<strong><?= h(date('D, d M · H:i',strtotime($booking['depart_at']))) ?></strong></span><span>Train / seats<strong><?= h($booking['train_code']) ?> · <?= h($booking['seats']) ?></strong></span><span>Fare<strong><?= money((float)$booking['total_fare']) ?></strong></span></div><div class="manage-actions"><a class="button secondary" href="?download=<?= (int)$booking['id'] ?>">Download ticket</a><?php if($booking['status']==='confirmed'): ?><p>Need a cancellation, refund or ticket change? <a href="?page=help#contact">Contact our demo support team</a>. Requests are handled by an administrator.</p><?php endif; ?></div></article><?php endif; ?><div class="hint-card"><span class="hint-mark">i</span><p>For this demo, passengers can look up their booking here. Staff process cancellation, refund and ticket-change requests in the admin area.</p></div></section>
